async () => {
  const b = await (await fetch('Inter.ttf')).arrayBuffer();
  const dv = new DataView(b); const n = dv.getUint16(4);
  let tags=[]; for(let i=0;i<n;i++){ let o=12+i*16; tags.push(String.fromCharCode(dv.getUint8(o),dv.getUint8(o+1),dv.getUint8(o+2),dv.getUint8(o+3))); }
  const h1=document.querySelector('h1');
  return {bytes:b.byteLength, hasFvar:tags.includes('fvar'), tags:tags.join(','), fonts:[...document.fonts].map(f=>f.family+' '+f.status), h1w:h1.getBoundingClientRect().height, scrollH:document.getElementById('page').scrollHeight};
}

