() => {
  const out=[]; const vw=innerWidth, vh=innerHeight;
  document.querySelectorAll('h1,.nm,.rl,.cta span,.step p,footer,.cand,.step').forEach(el=>{
    const r=el.getBoundingClientRect();
    const overflowX = el.scrollWidth > el.clientWidth+1;
    if(r.left<-0.5||r.right>vw+0.5||r.top<-0.5||r.bottom>vh+0.5||overflowX)
      out.push({t:el.className||el.tagName, txt:el.textContent.slice(0,20), r:[r.left,r.top,r.right,r.bottom], sw:el.scrollWidth, cw:el.clientWidth});
  });
  return {vw,vh,pageH:document.getElementById('page').scrollHeight, problems:out};
}

